import{_ as p}from"./chunks/image-002.Dp2-bnLm.js";import{_ as t}from"./chunks/image-005.C-lrs2Ft.js";import{_ as n,o,c as i,a3 as l}from"./chunks/framework.DdpBa4_E.js";const z=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/yan-tie-lun/08-通有第三.md","filePath":"books/yan-tie-lun/08-通有第三.md","lastUpdated":1794316978000}'),s={name:"books/yan-tie-lun/08-通有第三.md"};function r(_,a,e,m,c,d){return o(),i("div",null,[...a[0]||(a[0]=[l('<p>通有第三 【题解】</p><p>汉家实行均输政策的宗旨，是通过国家行政力量统管全国物资，用来调剂有无，实现物资的有效配置。本篇围绕货物要不要流通、要不要调剂有无的问题展开辩论。大夫认为货物流通有利于财富增殖，他从五行配五方的角度，说明均衡有无、流通万物是天地之道，进而又征引孔子关于俭不中礼的言论，说明一味节俭并不是正确的方法。文学则恪守以农为本的信念，主张“王者禁溢利，节漏费。溢利禁则反本，漏费节则民用给”。大夫强调的是货物流通带来的利益，而文学则更多地看到了工商业活动所带来的奢靡风气；前者否定力耕，显然对农业之本不利；而后者反对货物流通，则显然有闭关锁国之嫌。</p><p>大夫曰：“燕之涿、蓟[(1)]，赵之邯郸[(2)]，魏之温、轵[(3)]，韩之荥阳[(4)]，齐之临淄[(5)]，楚之宛、陈[(6)]，郑之阳翟[(7)]，三川之二周[(8)]，富冠海内，皆为天下名都，非有助之耕其野而田其地者也[(9)]，居五诸之冲，跨街衢之路也[(10)]。故物丰者民衍[(11)]，宅近市者家富。富在术数[(12)]，不在劳身；利在势居[(13)]，不在力耕也。”</p><p>【注释】</p><p>[(1)]燕：西周诸侯国，辖地在今北京、天津一带。涿：地名，原燕国都市，在今河北涿州。蓟：春秋战国燕国首都，在今北京大兴西南。</p><p>[(2)]赵：战国诸侯国，辖地在今河北南部、河南北部、山西中部和陕西东北隅。邯郸：地名，战国赵国首都，在今河北邯郸。</p><p>[(3)]魏：战国诸侯国，辖地在今河南北部、山西西南部。温：地名，在今河南温县。轵（zhì）：地名，在今河南济源。</p><p>[(4)]韩：战国诸侯国，辖地在今陕西东部、河南西北部。荥（xínɡ）阳：地名，原韩国都市，在今河南荥阳。</p><p>[(5)]齐：西周诸侯国，辖地在今山东北部、河南西南部。临淄：齐国都城，在今山东临淄。</p><p>[(6)]楚：西周诸侯国，全盛期的楚国辖地主要在湖北、湖南及豫、皖、江、浙部分地区。宛：地名，在今河南南阳。陈：本为西周诸侯国，后被楚所灭，治所在今河南淮阳。宛、陈，原作“宛丘”，据王先谦说校改。</p><p>[(7)]郑：西周诸侯国，在今河南中部一带。阳翟（dí）：地名，在今河南禹州。</p><p>[(8)]三川：伊水、洛水、黄河。二周：指战国时期的西周和东周，治所分别在河南洛阳西和巩县。</p><p>[(9)]田：用做动词，种植。</p><p>[(10)]居五诸之冲，跨街衢（qú）之路也：原作“居五诸侯之衢，跨街冲之路也”，据陈遵默、王利器说校改。五诸，即五都，汉代五都指洛阳、邯郸、临淄、宛城、成都。冲，交通要道。衢，四通八达的道路。</p><p>[(11)]民衍：民众富裕。</p><p>[(12)]术数：筹划。</p><p>[(13)]势居：地势优越。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“燕地的涿和蓟，赵地的邯郸，魏地的温和轵，韩地的荥阳，齐地的临淄，楚地的宛和陈，郑地的阳翟，伊水、洛水、黄河流域的东周西周，富裕冠于海内，都是天下有名都市，它们并不是借助于耕种田地而致富，而是居于五大都市的要道，处于交通枢纽之上。因此物产丰富的地方民众富有，住宅靠近都市的家庭富裕。致富在于筹划，不在于亲身劳动；获利在于地势优越，不在于努力耕作。”</p><p>文学曰：“荆、扬南有桂林之饶[(1)]，内有江、湖之利，左陵阳之金[(2)]，右蜀、汉之材[(3)]，伐木而树谷[(4)]，燔莱而播粟[(5)]，火耕而水耨[(6)]，地广而饶财；然民鮆窳偷生[(7)]，好衣甘食，虽白屋草庐[(8)]，歌讴鼓琴，日给月单[(9)]，朝歌暮戚[(10)]。赵、中山带大河[(11)]，纂四通神衢[(12)]，当天下之蹊[(13)]，商贾错于路[(14)]，诸侯交于道；然民淫好末，侈靡而不务本[(15)]，田畴不修[(16)]，男女矜饰[(17)]，家无斗筲[(18)]，鸣琴在室。是以楚、赵之民，均贫而寡富。宋、卫、韩、梁[(19)]，好本稼穑，编户齐民[(20)]，无不家衍人给[(21)]。故利在自惜[(22)]，不在势居街衢；富在俭力趣时[(23)]，不在岁司羽鸠也[(24)]。”</p><p>【注释】</p><p>[(1)]扬：原作“阳”，据王利器说校改。</p><p>[(2)]陵阳：在今安徽铜陵一带。金：黄铜。</p><p>[(3)]蜀：指西汉时的蜀郡，在今四川北部。汉：汉中郡，在今陕西南部和湖北西北部。</p><p>[(4)]树谷：种植庄稼。</p><p>[(5)]燔（fán）莱：焚烧荒草。播粟：播种庄稼。</p><p>[(6)]火耕：古代开荒种地，先放火烧尽柴草，而后耕作播种。水耨（nòu）：古代一种除草方法，放水将草沤烂。</p><p>[(7)]然民：原作“然后”，据王利器说校改。鮆窳（jì yǔ）：懒惰。</p><p>[(8)]白屋草庐：白茅草屋。</p><p>[(9)]日给月单：过得了一天，过不了一个月，即月光族。给，丰足。单，通“殚”，尽。</p><p>[(10)]朝歌暮戚：早上唱歌，晚上忧愁。</p><p>[(11)]中山：汉中山国，在今河北定县。带大河：以黄河为带，即靠近黄河。</p><p>[(12)]纂（zuàn）四通神衢：汇合四通八达的要冲。纂，汇合，连接。</p><p>[(13)]蹊（xī）：道路。</p><p>[(14)]错：交叉来往。</p><p>[(15)]侈靡：奢侈浪费。</p><p>[(16)]田畴：田地。修：整治。</p><p>[(17)]矜饰：讲究修饰打扮。</p><p>[(18)]家无斗筲（shāo）：家中连一斗或一筲的粮食都没有。筲，古代盛饭或装粮食的竹器。</p><p>[(19)]宋：西周诸侯国，在今河南商丘以东至江苏铜山县以西一带。卫：西周诸侯国，今河南濮阳一带。梁：春秋时期和汉代均有梁国。春秋梁国故址在今陕西韩城，后被秦国所灭。汉代梁国辖地包括今河南商丘和安徽北部地区、山东西南部分地区。战国魏国亦称梁。此处应指汉代梁国。</p><p>[(20)]编户：编入户口册内的人。齐民：平民。</p><p>[(21)]衍：富裕。</p><p>[(22)]自惜：自我珍惜。</p><p>[(23)]趣：通“趋”。</p><p>[(24)]岁司：管理农时。羽鸠：周时征收羽、鸠两种赋税的官吏名，此处指聚敛。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“荆州、扬州南有桂林的丰饶，内有长江、湖泊的利益，左边有铜陵的黄铜，右边有蜀、汉的木材，砍伐树木，种植庄稼，焚烧草木，播种五谷，以火耕地，以水耨草，土地广阔，财富丰饶。但民众懒惰偷生，喜欢鲜衣美食，即使住在在白茅草屋里，也要歌唱弹琴，过得了一天，过不了一个月，早上唱歌，晚上忧愁。赵地和中山靠近黄河，汇合四通八达的要冲，是天下人必经之路，商贾在路上交叉往来，诸侯交接于道路。然而民众过分喜欢经商，奢侈浪费，不愿务农，田地不整治，男女讲究修饰打扮，家中即使没有一斗一筲余粮，仍然在家弹琴作乐。所以楚地、赵地民众，大都贫穷而少有富人。宋、卫、韩、梁四地，爱好农耕，凡编入户籍的平民，无不是家家富裕，人人丰足。因此获利在于自我珍惜，不在于地处街道要冲；致富在于节俭，努力按时耕种，不在于每年派官吏从事于羽鸠赋税的征收。”</p><p>大夫曰：“五行[(1)]：东方木[(2)]，而丹、章有金铜之山[(3)]；南方火，而交趾有大海之川[(4)]；西方金，而蜀、陇有名材之林；北方水，而幽都有积沙之地[(5)]。此天地所以均有无而通万物也[(6)]。今吴、越之竹[(7)]，隋、唐之材[(8)]，不可胜用，而曹、卫、梁、宋[(9)]，采棺转尸[(10)]；江、湖之鱼，莱、黄之鲐[(11)]，不可胜食，而邹、鲁、周、韩[(12)]，藜藿蔬食[(13)]。天地之利无不赡[(14)]，而山海之货无不富也；然百姓匮乏，财用不足，多寡不调，而天下财不散也[(15)]。”</p><p>【注释】</p><p>[(1)]五行：金、木、水、火、土。</p><p>[(2)]东方木：战国秦汉五行家将五行与东南西北中相配一东方木，西方金，南方火，北方水，中央土。</p><p>[(3)]丹：丹阳郡，在今江苏、安徽长江以南地区。章：章山，在今江西南城县东北。</p><p>[(4)]交趾：汉郡名，在今广东、广西、越南北部地区。大海之川：即南海。</p><p>[(5)]幽都：幽州，在今河北北部、山东半岛及辽宁等地。积沙之地：指沙漠。</p><p>[(6)]均：平均。通：流通。</p><p>[(7)]吴：西周诸侯国，在今长江下游一带。越：夏商周古国，在今浙江一带。</p><p>[(8)]隋：通“随”，春秋诸侯国，在今湖北随州南。唐：春秋诸侯国，在今河南唐河。一说，在今湖北唐城。</p><p>[(9)]曹：西周诸侯国，在今山东曹县。卫：西周诸侯国，在今河南滑县。梁：春秋诸侯国，在今陕西韩城。宋：西周诸侯国，在今河南东部和山东、江苏、安徽部分地区。</p><p>[(10)]采棺：用柞木制作的简陋棺材。转尸：抛弃尸体。</p><p>[(11)]莱：西周诸侯国，在今山东龙口东南。黄：在今山东黄县。鲐（tái）：一种海鱼。</p><p>[(12)]邹：西周诸侯国，在今山东邹县。鲁：周公封国，今山东西南。周：夏商古国，今陕西岐山县。</p><p>[(13)]藜：一种野菜。藿（huò）：豆叶。</p><p>[(14)]赡：丰足，丰富。</p><p>[(15)]散：疏散。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“按照金、木、水、火、土五行：东方属木，而丹阳、章山却有金铜矿山；南方属火，而交趾郡却有浩瀚的南海；西方属金，而蜀郡、陇西郡却有名贵木材树林；北方属水，而幽州却有沙漠。这些都是天地用来平均有无而流通万物的。如今吴地、越地的竹子，随地、唐地的木材，多得用不完，而曹地、卫地、梁地、宋地，却用柞木做简陋棺材，有的甚至抛弃尸体；长江、湖泊的鱼类，莱地、黄地的鲐鱼，多得吃不完，而邹地、鲁地、周地、韩地，却以藜藿野菜和蔬菜为食。天地的财利无不丰足，山林河海的货物无不丰富；然而老百姓生活匮乏，财用不足，这是财物多少的分布不均匀，天下财物没有疏散的缘故。”</p><p>文学曰：“古者，采椽不斫[(1)]，茅茨不翦[(2)]，衣布褐[(3)]，饭土硎[(4)]，铸金为</p><p><img src="'+t+'" alt="" loading="lazy"></p><p>[(5)]，埏埴为器[(6)]，工不造奇巧[(7)]，世不宝不可衣食之物[(8)]，各安其居，乐其俗，甘其食，便其器。是以远方之物不交，而昆山之玉不至。今世俗坏而竞于淫靡[(9)]，女极纤微[(10)]，工极技巧[(11)]，雕素朴而尚珍怪[(12)]，钻山石而求金银[(13)]，没深渊求珠玑[(14)]，设机陷求犀象[(15)]，张网罗求翡翠[(16)]，求蛮、貉之物以眩中国[(17)]，徙邛、筰之货[(18)]，致之东海[(19)]，交万里之财，旷日费功[(20)]，无益于用。是以褐夫匹妇[(21)]，劳罢力屈[(22)]，而衣食不足也。故王者禁溢利[(23)]，节漏费[(24)]。溢利禁则反本，漏费节则民用给。是以生无乏资，死无转尸也。”</p><p>【注释】</p><p>[(1)]采：同“棌”，栎木。椽（chuán）：屋上承接瓦的木条。斫（zhuó）：砍削，雕饰。</p><p>[(2)]茅：茅草。原作“屋”，据王利器说校改。茨：用茅草盖屋顶。翦：同“剪”，修剪整齐。</p><p>[(3)]褐：粗布短衣。</p><p>[(4)]饭：用做动词，吃饭。土硎（xínɡ）：土做的饮食器具，即陶碗。</p><p>[(5)]金：金属，指铜铁。</p><p><img src="'+t+'" alt="" loading="lazy"></p><p>：同“锄”。</p><p>[(6)]埏埴（shān zhí）为器：糅合泥土来制作饮食器具。埏埴，糅合泥土。</p><p>[(7)]奇巧：奇异怪巧。</p><p>[(8)]宝：此处用作动词，以……为宝。</p><p>[(9)]淫靡：奢侈浪费。</p><p>[(10)]女极纤微：妇女手工制品要求极其精细。</p><p>[(11)]工极技巧：工匠制品要求极其奇巧。</p><p>[(12)]雕素朴：雕琢素朴的东西。尚珍怪：崇尚珍奇怪物。</p><p>[(13)]钻山石：开山凿石，指采掘金属矿产。</p><p>[(14)]没深渊：潜入深水。</p><p>[(15)]设机陷：设置捕捉动物的机关陷阱。犀：犀牛。象：大象。</p><p>[(16)]翡翠：一种珍贵的鸟，羽毛可做装饰品。</p><p>[(17)]蛮：南蛮，指南方少数民族。貉（mò）：同“貊”，指东北少数民族。眩（xuàn）：迷乱。</p><p>[(18)]邛（qiónɡ）：古代西南少数民族国名，在今四川西昌东南。筰（zuó）：古代西南少数民族，在今四川汉源县东南。</p><p>[(19)]东海：泛指东部靠海地区。</p><p>[(20)]旷日：耽误时日。</p><p>[(21)]褐夫：穿粗布衣的丈夫，此指普通平民。褐，原作“揭”，据王利器说校改。</p><p>[(22)]罢：同“疲”。力屈：力竭。</p><p>[(23)]溢利：暴利。</p><p>[(24)]漏费：不必要的费用。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“古时候，栎木椽子不用砍削，茅草盖屋不用修剪，穿的是粗布衣，吃饭用的是陶碗，把铜铁铸成锄头，糅合泥土成为器具，工匠不制造奇异怪巧的制品，世人不以不能吃穿的东西为宝，人人都安心住在自己居住的地方，喜欢当地风俗，甜美地吃着自己的食物，习惯使用自己的器具。所以远方的货物不去交易，昆仑山的宝玉也运不到。如今世俗败坏，竞相奢侈浪费，妇女手工制品要求极其精细，工匠制品要求极其奇巧，雕琢素朴的东西，崇尚珍奇怪物，开山凿石来寻找金银，潜入深水来寻求珠玑，设置机关陷阱来捕捉犀牛大象，张设网罗来猎捕翡翠，寻求边远蛮荒地区的宝物来迷乱中国，转运邛、筰的货物，到达东边沿海地区，交流万里之外的财物，耽误时日，耗费功效，无益于实用。所以平民夫妇，忙得精疲力竭，却衣食不足。因此君王禁止暴利，节约不必要的费用。暴利被禁止就会返回农业根本，不必要的费用被节约下来，就会民用充足。所以活着的时候不乏资财，死后也不会被抛尸荒野。”</p><p>大夫曰：“古者，宫室有度[(1)]，舆服以庸[(2)]；采椽茅茨，非先生之制也[(3)]。君子节奢刺俭，俭则固[(4)]。昔孙叔敖相楚[(5)]，妻不衣帛[(6)]，马不秣粟[(7)]。孔子曰：‘不可，大俭极下。’[(8)]此《蟋蟀》所为作也[(9)]。《管子》曰[(10)]：‘不饰宫室，则材木不可胜用，不充庖厨[(11)]，则禽兽不损其寿。无末利[(12)]，则本业无所出，无黼黻[(13)]，则女工不施[(14)]。’故工商梓匠[(15)]，邦国之用，器械之备也。自古有之，非独于此。弦高贩牛于周[(16)]，五羖赁车入秦[(17)]，公输子以规矩[(18)]，欧冶以镕铸[(19)]。《语》曰：‘百工居肆，以致其事。’[(20)]农商交易，以利本末。山居泽处，蓬蒿墝埆[(21)]，财物流通，有以均之[(22)]。是以多者不独衍[(23)]，少者不独馑[(24)]。若各居其处，食其食，则是橘柚不鬻，朐卤之盐不出[(25)]，旃罽不市，而吴、唐之材不用也。”</p><p>【注释】</p><p>[(1)]度：等级制度。</p><p>[(2)]舆：车马。服：衣冠服饰。庸：功劳。</p><p>[(3)]先生：疑为“先王”，因“生”与“王”形近而误。</p><p>[(4)]固：粗陋。</p><p>[(5)]孙叔敖：春秋时期楚庄王贤相。</p><p>[(6)]衣帛：穿丝帛衣服。</p><p>[(7)]秣粟：喂粮食。秣，喂马。</p><p>[(8)]不可，大俭极下：未见出处。大，同“太”。极下，接近下级，指体现不了等级差别。</p><p>[(9)]《蟋蟀》：《诗经·唐风》中的作品。《毛诗序》：“《蟋蟀》，刺晋僖公也。俭不中礼，故作是诗以闵之，欲其及时以礼自虞乐也。”</p><p>[(10)]《管子》曰：今本《管子》中没有所引这一节文字。</p><p>[(11)]充：充实。庖厨：厨房。</p><p>[(12)]末利：指工商业。末，原作“味”，据王先谦说校改。</p><p>[(13)]黼黻（fǔ fú）：古代绘绣的具有华美花纹的礼服。</p><p>[(14)]不施：无所施展技巧。</p><p>[(15)]梓匠：木匠。</p><p>[(16)]弦高：春秋时期郑国商人。贩：原作“饭”，据洪颐煊说校改。周：指洛阳。公元前627年，弦高到周地贩牛，路过滑地，遇到前来偷袭的秦军，便一面以郑君使者名义，用十二头牛犒赏秦军，一面派人报告郑君。秦军以为郑国已有防备，只好退兵。</p><p>[(17)]五羖（ɡǔ）：指百里奚。羖，黑色的公羊。赁（lìn）车：租车。《史记·秦本纪》载：“五年，晋献公灭虞、虢，虏虞君与其大夫百里傒，以璧马赂于虞故也。既虏百里傒，以为秦穆公夫人媵于秦。百里傒亡秦走宛，楚鄙人执之。穆公闻百里傒贤，欲重赎之。恐楚人不与，乃使人谓楚曰：‘吾媵臣百里傒在焉，请以五羖羊皮赎之。’楚人遂许与之。当是时，百里傒年已七十余。穆公释其囚，与语国事。谢曰：‘臣亡国之臣，何足问！’穆公曰：‘虞君不用子，故亡，非子罪也。’固问，语三日，穆公大说，授之国政，号曰五羖大夫。”</p><p>[(18)]公输子：鲁班，战国初年鲁国能工巧匠。规：圆规。矩：量方的曲尺。</p><p>[(19)]欧冶：即欧冶子，春秋末期越国人，善于铸剑。</p><p>[(20)]百工居肆，以致其事：见于《论语·子张》。百工，各种手工艺匠人。肆，手工作坊。</p><p>[(21)]蓬蒿：野草。墝埆（qiāo què）：土地贫瘠。</p><p>[(22)]均之：均衡。</p><p>[(23)]衍：富裕。</p><p>[(24)]馑（jǐn）：同“堇”，缺乏。</p><p>[(25)]朐（qú）：秦县，在今江苏连云港西南。卤：盐卤。一说，卤为汉县，属安定郡，在今甘肃或宁夏回族自治区境内。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“古时候，宫室有等级制度，车马衣服按照功劳大小而定；栎木椽子和茅草盖屋，并不是先王的制度。君子节制奢侈讥刺俭朴，因为俭朴就会粗陋。从前孙叔敖为楚国令尹，妻子不穿丝帛衣服，马不喂粮。孔子说：‘不可以这样做，太俭朴就与下级分不出等级。’这就是《诗经·唐风·蟋蟀》创作的原因啊。《管子》说：‘不修饰宫室，材木就用不完，不充实厨房，禽兽就不会减少寿命。如果没有工商业，那么农业就无从发展，没有黼黻礼服，那么女工就不能施展技艺。’因此工商木匠，都是对国家有用的人，他们能够提供器械设备。自古以来就有工商匠人，并不是今天才有的。弦高到东周贩牛，五羖大夫百里奚曾受雇租车到秦国经商，公输班凭借圆规曲尺而成为能工巧匠，欧冶子凭借镕铸技术而成为铸剑高手。《论语·子张》说：‘各种工匠居住在作坊，尽力完成他们的工作。’农业与商业交易，有利于农业和工商业的发展。有些人住在山里，或处于湖畔，野草丛生，土地贫瘠，更应该加强财物流通，想办法均衡特产。所以特产多的地方不独自富裕，特产少的地方不独自贫乏。如果各自居住在自己那个地方，吃那个地方的食物，那么有些盛产橘柚的地方就卖不出去，朐县的盐也运不出，毡子地毯都不能上市，吴地、唐地的竹子和木材就没有用了。”</p><p>文学曰：“孟子云：‘不违农时，谷不可胜食。蚕麻以时，布帛不可胜衣也。斧斤以时，材木不可胜用。田渔以时，鱼肉不可胜食。’[(1)]若则饰宫室[(2)]，增台榭[(3)]，梓匠斫巨为小，以圆为方，上成云气[(4)]，下成山林，则材木不足用也。男子去本为末，雕文刻镂，以象禽兽，穷物究变[(5)]，则谷不足食也。妇女饰微治细[(6)]，以成文章[(7)]，极伎尽巧[(8)]，则丝布不足衣也。庖宰烹杀胎卵[(9)]，煎炙齐和[(10)]，穷极五味[(11)]，则鱼肉不足食也。当今世，非患禽兽不损[(12)]，材木不胜[(13)]，患僭侈之无穷也[(14)]；非患无旃罽橘柚，患无狭庐糠糟也[(15)]。”</p><p>【注释】</p><p>[(1)]不违农时，谷不可胜食。蚕麻以时，布帛不可胜衣也。斧斤以时，材木不可胜用。田渔以时，鱼肉不可胜食：见于《孟子·梁惠王上》。按，“以时”之下原有“入”字，据王利器说校删。</p><p>[(2)]若则：如果。</p><p>[(3)]台榭（xiè）：亭台上的房屋。</p><p>[(4)]云气：指宫室台榭上雕刻的云彩花纹。</p><p>[(5)]穷物究变：雕刻时穷尽事物变化。</p><p>[(6)]饰微治细：刺绣精细。</p><p>[(7)]文章：花纹。</p><p>[(8)]伎：通“技”。</p><p>[(9)]胎卵：兽胎蛋卵。</p><p>[(10)]灸：烧烤。齐和：以五味调和。齐，同“剂”。</p><p>[(11)]五味：酸、苦、甘、辛、咸。</p><p>[(12)]损：减少寿命。</p><p>[(13)]不胜：用不尽。</p><p>[(14)]僭（jiàn）侈：僭越奢侈。</p><p>[(15)]狭庐：狭小的茅屋。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“孟子说过：‘不违农时，谷子就吃不完。蚕麻按时养织，粗布丝帛就穿不完。斧斤按时节进山砍伐，材木就用不完。按照时节打猎捕鱼，鱼肉就吃不完。’如果无休无止地修饰宫室，增建亭台楼榭，木匠把大木料砍成小木料，把圆木砍为方木，上面雕刻云气，下面雕刻山林，那么材木就不够用。男子弃农经商，雕刻镂画，描摹禽兽，穷尽事物变化，那么谷子就不够吃。妇女刺绣精细，构成花纹，极尽技巧，那么丝帛粗布就不够穿。厨师烹杀兽胎蛋卵，煎烤调和，穷尽酸、苦、甘、辛、咸五味，那么鱼肉就不够吃。当今之世，不怕禽兽不减少，材木用不完，而是怕僭越、奢侈之风无穷无尽；不怕没有毡子、毛毯、橘子、柚子，而是怕没有狭小的茅屋和糠糟。”</p>',152)])])}const y=n(s,[["render",r]]);export{z as __pageData,y as default};
